"""Concrete eager surfaces (hand-written for the MVP; to be generated by
``webclient.gen`` from the Cores' fields + backings)."""
from __future__ import annotations

from typing import Any

from .core.client_core import WebClientCore
from .core.document_core import DocumentCore
from .core.reference_core import HttpMethod, ReferenceCore
from .core.reference_core import from_url as _core_from_url
from .surface import Surface, surface


@surface(ReferenceCore)
class Reference(Surface):
    """A request spec (eager): ``url``/``with_params``/``replace``/``join``/
    ``resolve``."""


@surface(DocumentCore)
class Document(Surface):
    """A resolved document (eager): ``select``/``select_all``/``attr``/``text``
    (render/live/events are later slices)."""


def from_url(url: str, method: HttpMethod = "get",
             params: dict[str, str | list[str]] | None = None,
             headers: dict[str, str] | None = None,
             cookies: dict[str, str] | None = None) -> Reference:
    """Build a :class:`Reference` from a URL string."""
    return Reference(_core_from_url(url, method, params, headers, cookies))


class Renderer:
    """A (kind, format) render override -- register with ``wc.use``. Subclass
    and set ``name``/``kind``/``formats`` and implement ``render``."""

    name: str = ""
    kind: str = "html"
    formats: list[str] = []

    def render(self, document: "Document", format: str, **options: Any) -> Any:
        raise NotImplementedError


class WebClient:
    """The synchronous client surface (MVP): fetch a URL into a Document, or
    build a client-bound Reference to resolve. Owns a ``WebClientCore``."""

    def __init__(self, **policy: Any) -> None:
        self._core = WebClientCore(**policy)

    @property
    def bus(self) -> Any:
        """The client's event bus (subscribe to network/dom/console topics)."""
        return self._core.bus

    def use(self, renderer: Renderer) -> "WebClient":
        self._core.use(renderer)
        return self

    def ref(self, url: str, method: HttpMethod = "get", **kw: Any) -> Any:
        """A lazy client-bound reference: ``wc.ref(url).resolve()...collect()``
        (statically a ``Reference``; at runtime an Expr recording a plan)."""
        from .expr import Expr
        from .plan import Plan
        spec = _core_from_url(url, method, **kw).model_dump()
        return Expr(Plan(root="Reference", source=spec), self._core)

    #: ``wc.lazy`` is the same bound reference root as ``wc.ref``.
    lazy = ref

    def fetch(self, url: str, *, optional: bool = False, error: Any = None,
              **kw: Any) -> Any:
        """A lazy fetch: ``ref(url).resolve()``; ``.collect()`` to materialise."""
        return self.ref(url, **kw).resolve(optional=optional, error=error)

    def document(self, name: str) -> Document:
        """Recover a materialised Document by name (same surface object)."""
        from .surface import wrap
        return wrap(self._core.document(name))

    def reference(self, name: str) -> Reference:
        """Recover a Reference by its (root) name (same surface object)."""
        from .surface import wrap
        return wrap(self._core.reference(name))

    def execute(self, expr: Any, context: Any = None, *, stream: bool = False,
                **kw: Any) -> Any:
        """Run a recorded lazy plan on this client. Returns the plan's result
        (a scalar, a surface, or the rows). ``stream=True`` yields rows (MVP:
        sequential, so the rows are materialised then iterated)."""
        from .executor import evaluate
        result = evaluate(expr, context, client=self._core)
        return iter(result) if stream and isinstance(result, list) else result

    def close(self) -> None:
        self._core.close()

    def __enter__(self) -> "WebClient":
        return self

    def __exit__(self, *exc: object) -> None:
        self._core.close()


__all__ = ["Reference", "Document", "WebClient", "from_url"]
